def walk(v,p=''):
 if isinstance(v,dict):
  for k,w in v.items():yield from walk(w,p+'/'+str(k).replace('~','~0').replace('/','~1'))
 elif isinstance(v,list):
  for i,w in enumerate(v):yield from walk(w,p+'/'+str(i))
 elif isinstance(v,str):yield p,v
